import json
import os
import re
from http.server import HTTPServer, BaseHTTPRequestHandler
from decimal import Decimal, ROUND_HALF_UP, InvalidOperation

# Server-side history storage (in-memory, max 20 entries)
history = []
MAX_HISTORY = 20


class ArithmeticParser:
    """
    Recursive descent parser for arithmetic expressions.
    Supports: +, -, *, /, parentheses, unary minus, decimals.
    """

    def __init__(self, expression):
        self.expression = expression
        self.pos = 0
        self.tokens = self._tokenize()
        self.token_pos = 0

    def _tokenize(self):
        """Tokenize the expression into numbers and operators."""
        tokens = []
        expr = self.expression.replace(' ', '')

        if not expr:
            raise ValueError("Empty expression")

        i = 0
        while i < len(expr):
            char = expr[i]

            if char in '+-*/()':
                tokens.append(char)
                i += 1
            elif char.isdigit() or char == '.':
                # Parse number
                num_str = ''
                has_dot = False
                while i < len(expr) and (expr[i].isdigit() or expr[i] == '.'):
                    if expr[i] == '.':
                        if has_dot:
                            raise ValueError("Invalid number format")
                        has_dot = True
                    num_str += expr[i]
                    i += 1
                if num_str == '.' or num_str.endswith('.') and len(num_str) == 1:
                    raise ValueError("Invalid number format")
                tokens.append(('NUM', num_str))
            else:
                raise ValueError(f"Invalid character: {char}")

        return tokens

    def _current_token(self):
        if self.token_pos < len(self.tokens):
            return self.tokens[self.token_pos]
        return None

    def _consume(self, expected=None):
        token = self._current_token()
        if expected is not None and token != expected:
            raise ValueError(f"Expected {expected}, got {token}")
        self.token_pos += 1
        return token

    def parse(self):
        """Parse and evaluate the expression."""
        if not self.tokens:
            raise ValueError("Empty expression")
        result = self._parse_expression()
        if self._current_token() is not None:
            raise ValueError("Unexpected token at end of expression")
        return result

    def _parse_expression(self):
        """Parse addition and subtraction (lowest precedence)."""
        left = self._parse_term()

        while self._current_token() in ('+', '-'):
            op = self._consume()
            right = self._parse_term()
            if op == '+':
                left = left + right
            else:
                left = left - right

        return left

    def _parse_term(self):
        """Parse multiplication and division (higher precedence)."""
        left = self._parse_factor()

        while self._current_token() in ('*', '/'):
            op = self._consume()
            right = self._parse_factor()
            if op == '*':
                left = left * right
            else:
                if right == 0:
                    raise ValueError("Division by zero")
                left = left / right

        return left

    def _parse_factor(self):
        """Parse unary minus, parentheses, and numbers."""
        token = self._current_token()

        # Handle unary minus
        if token == '-':
            self._consume()
            return -self._parse_factor()

        # Handle unary plus (optional)
        if token == '+':
            self._consume()
            return self._parse_factor()

        # Handle parentheses
        if token == '(':
            self._consume()
            result = self._parse_expression()
            if self._current_token() != ')':
                raise ValueError("Unbalanced parentheses")
            self._consume()
            return result

        # Handle numbers
        if isinstance(token, tuple) and token[0] == 'NUM':
            self._consume()
            return Decimal(token[1])

        if token == ')':
            raise ValueError("Unexpected closing parenthesis")

        raise ValueError("Expected number or expression")


